#!/usr/bin/env python3
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

# The Builder may keep running after a dev submission is frozen.  Keep
# interpreter-generated bytecode out of the editable submission so its digest
# remains stable through the final Builder artifact check.
sys.dont_write_bytecode = True

from productivity_policy import prediction_for


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--run-dir", type=Path, required=True)
    args = parser.parse_args()
    rows = [prediction_for(json.loads(line)) for line in args.input.read_text(encoding="utf-8").splitlines() if line.strip()]
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.run_dir.mkdir(parents=True, exist_ok=True)
    args.output.write_text("".join(json.dumps(row) + "\n" for row in rows), encoding="utf-8")
    (args.run_dir / "run_report.json").write_text(json.dumps({"status": "ok", "artifact_paths": [str(args.output)], "errors": [], "usage": {}}, indent=2) + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
